from __future__ import annotations

from typing import Self, Dict

import weakref
from phoenix.keymap import KeyMap, Key


class InstructionVariable:
    """Represents the offset of a variable in an instruction"""

    # every variable is derived as a subclass
    # every instance represents a certain entry in that class

    _count: int = 0

    def __init__(
        self,
        name,
        *params,
        history=None,
        offsets=None,
        input_config=None,
        output_config=None,
    ):
        if offsets is None:
            offsets = []
        if history is None:
            history = []
        self._name = name
        self._history = history
        self._offsets = offsets
        self._inp_config = None
        self._out_config = None
        self.input_config = input_config
        self.output_config = output_config
        self.progress(*params)

    def __str__(self):
        offset = (
            f"({'|'.join(map(str, self.offsets))})" if self.offsets else "O"
        )
        return f"<{self._name}+{offset}>"

    def __repr__(self):
        return f"<{self._name}>"

    @property
    def name(self):
        """access name attribute"""
        return self._name

    @property
    def offsets(self):
        """access offsets"""
        return list(self._offsets)

    @property
    def offset(self):
        """access total offset"""
        return "(" + "+".join(str(offs) for offs in self._offsets) + ")"

    @property
    def input_config(self):
        """access read-only attribute input_config"""
        if self._inp_config is None:
            return None
        return self._inp_config()

    @input_config.setter
    def input_config(self, target):
        if target is None:
            self._inp_config = None
            return
        self._inp_config = weakref.ref(target)

    @property
    def output_config(self):
        """access read-only attribute output_config"""
        if self._out_config is None:
            return None
        return self._out_config()

    @output_config.setter
    def output_config(self, target):
        if target is None:
            self._out_config = None
            return
        self._out_config = weakref.ref(target)

    @property
    def history(self):
        """access offsets"""
        return list(self._history)

    def copy(self):
        """return a copy"""
        return self.__class__(
            name=self._name,
            offsets=list(self._offsets),
            history=list(self._history),
            input_config=self.input_config,
            output_config=self.output_config,
        )

    def combine(self, other):
        """combine two variables"""
        if not self.is_compatible_before(other):
            raise ValueError("Incompatible Variables cannot be combined")
        return InstructionVariable(
            name=self.name,
            history=self.history + other.history,
            offsets=self.offsets + other.offsets,
            input_config=self.input_config,
            output_config=other.output_config,
        )

    def progress(self, *params):
        """progress the position of the variable in memory"""
        for param in params:
            self._offsets.append(param)
            self._history.append(param)
        return self

    def __call__(self, *params):
        return self.copy().progress(*params)

    def __or__(self, other):
        return self.combine(other)

    def is_compatible_before(self, other):
        """check if the variables fit together"""
        if self.output_config is not None:
            if other.input_config is not None:
                if self.output_config != other.input_config:
                    return False
        return True


class KeyMapInstructionVariable(InstructionVariable):
    """
    KeyMapInstructionVar

    Represents a variable that is based on a keymap.

    The main purpose is that there is a representation of input and output
    variables in instructions. They can be assigned to the ADAAs and have
    information on datatype and names.

    Especially for the keymap-version, the variable can be progressed when we
    move along nested keymaps, accumulating offsets.

    """

    def __init__(
        self,
        name,
        *params,
        offsets=None,
        history=None,
        input_config=None,
        output_config=None,
        keymap=None,
    ):
        if keymap is not None:
            output_config = keymap
        if not offsets:
            if input_config is None:
                input_config = output_config
        super().__init__(
            name,
            *params,
            offsets=offsets,
            history=history,
            input_config=input_config,
            output_config=output_config,
        )
        # will resolve the key sequence params as seen from keymap

    def copy(self):
        """return a copy"""
        return self.__class__(
            name=self._name,
            offsets=list(self._offsets),
            history=list(self._history),
            input_config=self.input_config,
            output_config=self.output_config,
        )

    def progress(self, *params):
        """resolve num steps in param"""
        newpointer = self.output_config
        for param in params:
            assert newpointer is not None
            offset, newpointer = newpointer.goto(param)
            self._history.append(param)
            self.output_config = newpointer
            self._offsets.append(offset)
        self.output_config = newpointer
        return self


class SymbolicInstructionVariable(InstructionVariable):
    """A symbolic variable that supports the use of local LibVars"""

    def __init__(
        self,
        name,
        variable=None,
        offsets=None,
        history=None,
        input_config=None,
        output_config=None,
    ):
        self._variable = variable
        super().__init__(
            name=name,
            offsets=[variable or "?"],
            history=history,
            input_config=input_config,
            output_config=output_config,
        )

    def associate_variable(self, variable):
        """associate a variable"""
        if self._variable is not None:
            raise ValueError("Variable already associated")
        self._variable = variable
        self.progress()

    def progress(self, *values):
        if values:
            raise ValueError("Cannot progress symbolic variable")
        if self._variable is None:
            self._offsets = ["?"]
            self._history = []
        else:
            self._offsets = [self._variable]
            self._history = [self._variable]
        return self

    def copy(self):
        """return a copy"""
        return self.__class__(
            name=self.name,
            variable=self._variable,
            offsets=list(self._offsets),
            history=list(self._history),
            input_config=self._inp_config,
            output_config=self._out_config,
        )


class InstructionEnvironment:
    """Defines an instruction environment where all known variables can be stored"""

    def __init__(self, **variables):
        self._variables: Dict[str, InstructionVariable] = variables

    def items(self):
        """iterate through dict-like items"""
        yield from self._variables.items()

    def as_dict(self):
        """display as a dictionary"""
        return {key: val for key, val in self.items()}

    def copy(self) -> InstructionEnvironment:
        """make a proper copy"""
        return self.__class__(
            **{key: var.copy() for key, var in self._variables.items()}
        )

    def merge(
        self, other_environment: InstructionEnvironment
    ) -> InstructionEnvironment:
        """merge an environment with another"""
        new_environment = self.copy()
        new_environment.update(**other_environment.as_dict())
        return new_environment

    def __or__(self, other: InstructionEnvironment) -> InstructionEnvironment:
        return self.merge(other)

    def update(self, **kwargs):
        """update the internal dictionary. Extend if possible"""
        for varname, variable in kwargs.items():
            if varname in self._variables:
                self._variables[varname] |= variable
            else:
                self._variables[varname] = variable
        return self

    def keys(self):
        """access keys of inner dict"""
        return self._variables.keys()

    def __getitem__(self, key):
        return self._variables[key]

    def __contains__(self, key):
        return key in self._variables
